            let i = (y * width + x) * 4;
            let radius = 10;
            let center_x = width / 2;
            let center_y = height / 2;
            let radius_squared = radius * radius;
            let x_offset = center_x - radius;
            let y_offset = center_y - radius;
            let x = x_offset + radius;
            let y = y_offset + radius;
            let r = radius_squared - (x_squared + y_squared);
            let g = r * (x / (x_squared + y_squared));
            let b = r * (y / (x_squared + y_squared));
            pixels[i] = g;
            pixels[i + 1] = b;
            pixels[i + 2] = r;
            pixels[i + 3] = 255;
        }
    }
    pixels.as_ptr()
}

